import{z as o,x as s,o as A,c as d,q as r,j as n,D as a,d as e,s as i,S as l,b as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"事件研究的微观版本","description":"","frontmatter":{"title":"事件研究的微观版本","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/obd-eventstudy-micro.md","filePath":"quant/obd-eventstudy-micro.md","lastUpdated":1791063341000}'),C={name:"quant/obd-eventstudy-micro.md"};function p(D,E,F,m,u,c){const t=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=r('<h1 id="事件研究的微观版本" tabindex="-1">事件研究的微观版本 <a class="header-anchor" href="#事件研究的微观版本" aria-label="Permalink to &quot;事件研究的微观版本&quot;">​</a></h1><div class="epigraph"><p>规则类事件改变的不是现金流，是速率方程的系数——结果变量必须换成微观量，对照与机制也落在微观上。</p><footer>—— 据 MacKinlay, Journal of Economic Literature, 1997；Harris, Trading and Exchanges, 2003 整理</footer></div><p><a href="/quant/obd-hf-vol-noise">上一课</a>把微观读数做干净；本课起进入方法单元：把日频事件研究——主干<a href="/quant/event-study">事件研究</a>的窗口、正常收益模型与横截面推断——下放到微观事件：tick 调整、撮合迁移、竞价规则修改、费率变化、新 venue。结果变量不再是异常收益，而是前面几课的微观量；「微观版本」的含义就在这：机制同源，对象与推断协议换掉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>日频 machinery 不能直接搬。其一，微观结果变量有强日内形状与体制依赖（第五课），前后不控时点的比较里季节性冒充效应。其二，微观数据有强序列相关与横截面相关（第七课的共同因子），横截面独立假设失效，标准误系统性偏小。其三，事件常复合：tick 与费率同日改，单一归因从设计上不成立。缺口是微观版的设计协议：结果变量、对照、推断、功效不足时的出路。</p><p><span class="marginnote">术语翻译：双重差分就是「两次相减」——事件组前后一减，对照组前后一减，两个差再相减。共同的时间趋势（比如全市场流动性都在缓慢变好）在两次相减里互相抵消，剩下的部分才归给事件本身。</span></p><h3 id="结果变量与窗口" tabindex="-1">结果变量与窗口 <a class="header-anchor" href="#结果变量与窗口" aria-label="Permalink to &quot;结果变量与窗口&quot;">​</a></h3><p>结果变量逐一定义在微观量上：相对点差、各档深度、价格发现份额、\\(\\lambda\\) 口径、噪声方差、成交强度与竞价占比。窗口多两条约束：避开事件日过渡段——参与者迁移策略需要时间，过渡段既非旧体制也非新体制；对齐日内相位——比较窗口落在形状的同一相位上，否则第五课的形状差异直接进结果。</p><p><span class="marginnote">tick size 分级试点是微观事件研究的天然素材：同日不同组、跨票可比、规则外生。即便如此，两组的事前差异仍要先用历史数据钉死——平行趋势只是口头承诺时，双重差分给出的是精确的错觉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计四步。定义：事件日历、结果变量、假设方向，预注册口径——「效果好不好」式总结不算数据。对照：同期对照组做双重差分，按载荷匹配（流动性水平、波动、行业）；事件前形状是基线前提——形状不稳（第五课的崩坏清单）就没有干净基线，先剔除搬家日。推断：自相关与横截面相关用区块自助或双重聚类；单次事件功效天然弱，此时报告机制证据——系数变化的形状是否与机制预测一致（tick 变小应主要压缩价差，其次改变深度分布），而非只报显著性。稳健性：安慰剂事件、时移窗口、按体制分层重估。</p>',11)),(A(),n(l,null,{default:a(()=>[i(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E4%BA%8B%E4%BB%B6%E6%97%A5%E5%8E%86%20%2B%20%E7%BB%93%E6%9E%9C%E5%8F%98%E9%87%8F%20%2B%20%E5%81%87%E8%AE%BE%EF%BC%88%E9%A2%84%E6%B3%A8%E5%86%8C%EF%BC%89%22%5D%20--%3E%20CTRL%5B%22%E5%AF%B9%E7%85%A7%E7%BB%84%EF%BC%9A%E6%8C%89%E8%BD%BD%E8%8D%B7%E5%8C%B9%E9%85%8D%22%5D%0A%20%20CTRL%20--%3E%20DID%5B%22%E5%8F%8C%E9%87%8D%E5%B7%AE%E5%88%86%EF%BC%9A%E4%BA%8B%E4%BB%B6%E5%89%8D%E5%BD%A2%E7%8A%B6%E4%B8%BA%E5%9F%BA%E7%BA%BF%22%5D%0A%20%20DID%20--%3E%20INF%5B%22%E5%8C%BA%E5%9D%97%E8%87%AA%E5%8A%A9%2F%E5%8F%8C%E9%87%8D%E8%81%9A%E7%B1%BB%E6%8E%A8%E6%96%AD%22%5D%0A%20%20INF%20--%3E%20SIG%7B%22%E6%98%BE%E8%91%97%EF%BC%9F%22%7D%0A%20%20SIG%20--%3E%7C%E6%98%AF%7C%20MECH%5B%22%E6%9C%BA%E5%88%B6%E6%A0%B8%E5%AF%B9%EF%BC%9A%E7%B3%BB%E6%95%B0%E5%BD%A2%E7%8A%B6%E4%B8%8E%E9%A2%84%E6%B5%8B%E4%B8%80%E8%87%B4%EF%BC%9F%22%5D%0A%20%20SIG%20--%3E%7C%E5%90%A6%7C%20POWER%5B%22%E5%8A%9F%E6%95%88%E8%AF%8A%E6%96%AD%EF%BC%9A%E5%AE%89%E6%85%B0%E5%89%82%E4%B8%8E%E6%9C%BA%E5%88%B6%E8%AF%81%E6%8D%AE%22%5D%0A%20%20MECH%20--%3E%20CONC%5B%22%E5%BD%92%E5%9B%A0%EF%BC%9A%E5%8D%95%E4%B8%80%E5%8F%98%E9%87%8F%E8%BF%98%E6%98%AF%E5%A4%8D%E5%90%88%E4%BA%8B%E4%BB%B6%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[e("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"为什么可行：规则类事件改的是速率方程的系数——第一课的 \\(\\lambda\\) 族、点差的分布、竞价的透明度——这些量事件前后可测，测的就是机制本身。为什么功效弱：样本常常是「一个市场的同一段历史」，横截面全市场一起变，载荷分散不了。为什么机制证据在功效不足时仍有信息：若价差收窄伴随深度分布搬家而噪声方差不动，这与「tick 约束放松」的机制一致、与「整体流动性改善」的叙事不一致——机制核对让弱功效研究仍有累积价值。这与复盘课同构：判据落在机制上，不落在「显著」上。",-1)),E[5]||(E[5]=B("p",null,"两种竞争解释怎么靠微观量的形状分开，是机制核对的核心问题：",-1)),(A(),n(l,null,{default:a(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBS%5B%22%E8%A7%82%E6%B5%8B%3A%E4%BB%B7%E5%B7%AE%E6%94%B6%E7%AA%84%E4%BA%86%22%5D%20--%3E%20Q1%7B%22%E6%B7%B1%E5%BA%A6%E5%88%86%E5%B8%83%E6%90%AC%E5%AE%B6%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%3A%E6%9C%80%E5%B0%8F%E6%8A%A5%E4%BB%B7%E6%A1%A3%E6%98%8E%E6%98%BE%E5%8F%98%E5%AF%86%22%7C%20H1%5B%22%E4%B8%8E%20tick%20%E7%BA%A6%E6%9D%9F%E6%94%BE%E6%9D%BE%E4%B8%80%E8%87%B4%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%3A%E5%90%84%E6%A1%A3%E5%90%8C%E6%AF%94%E4%BE%8B%E5%8F%98%E5%8E%9A%22%7C%20H2%5B%22%E4%B8%8E%E6%95%B4%E4%BD%93%E6%B5%81%E5%8A%A8%E6%80%A7%E6%94%B9%E5%96%84%E4%B8%80%E8%87%B4%22%5D%0A%20%20OBS%20--%3E%20Q2%7B%22%E5%99%AA%E5%A3%B0%E6%96%B9%E5%B7%AE%E6%80%8E%E4%B9%88%E5%8A%A8%3F%22%7D%0A%20%20Q2%20--%3E%7C%22%E5%9F%BA%E6%9C%AC%E4%B8%8D%E5%8A%A8%22%7C%20H3%5B%22%E6%94%AF%E6%8C%81%20tick%20%E6%9C%BA%E5%88%B6%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%90%8C%E6%AD%A5%E4%B8%8A%E5%8D%87%22%7C%20H4%5B%22%E6%9B%B4%E5%83%8F%E6%B3%A2%E5%8A%A8%E9%A9%B1%E5%8A%A8%E7%9A%84%E6%94%B9%E5%96%84%22%5D%0A%20%20H1%20--%3E%20CONC%5B%22%E4%B8%A4%E6%9D%A1%E8%AF%81%E6%8D%AE%E4%BA%A4%E5%8F%89%2C%E9%94%81%E5%AE%9A%E6%9C%BA%E5%88%B6%22%5D%0A%20%20H3%20--%3E%20CONC%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">数字实例：若点差变化的序列相关让有效样本量只剩名义的四分之一，普通标准误就偏小一半——真实 t 只有 1.8（不显著）的效应，会被报成 t=3.6 的「高度显著」。这就是必须用区块自助或双重聚类重算标准误的原因。</span></p><p>错法：前后均值比较不控日内相位与共同因子；过渡段当新体制样本；复合事件声称单一归因；把日频结论（流动性改善）直接当微观机制（点差收窄来自哪一档）。</p><p><span class="marginnote">常见误区：初学者容易把「显著」当结论。微观事件往往只有一个样本——某个市场就改一次规则，功效天生不足；此时「系数变化的形状与机制预测一致」比 p 值更值得报告，它让这次事件仍能为累积知识出力。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>单次事件的因果链永远有缺口：对照再好也排不掉同时发生的未观测变化——机制证据是缓解不是消除。结果变量同源相关（点差、深度与噪声方差，上一课），当独立证据重复计数会夸大确定性。外部有效性受限：规则事件迁移到别的市场，前提是参与者结构相近。产出是速率系数的变化表，不是好坏评价——评价要接回市场质量的目标函数，属制度设计的另一门课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>换掉三件事：结果变量换成微观量、对照加日内相位与共同因子控制、推断用区块自助/双重聚类。</li><li>窗口避开过渡段；事件前形状是基线前提，形状搬家日先剔除。</li><li>单次事件功效天然弱：机制证据（系数形状核对）是主要的累积价值来源。</li><li>产出是速率系数的变化表，不是好坏评价。</li><li>出处：MacKinlay, <em>JEL</em>, 1997；设计对照见<a href="/quant/event-study">事件研究</a>；微观口径见 Harris, <em>Trading and Exchanges</em>, 2003。</li></ul>',7))])}const b=o(C,[["render",p]]);export{f as __pageData,b as default};
